const CONFIG=window.TRACKER_CONFIG||{},INSTALL_ROOT=new URL('./',location.href),CLIENT_ID=CONFIG.clientId||'',REDIRECT_URI=CONFIG.redirectUri||INSTALL_ROOT.href,TOKEN_KEY=CONFIG.tokenKey||('tracker:'+INSTALL_ROOT.pathname+':tokens'),AUTH="https://login.microsoftonline.com/common/oauth2/v2.0",GRAPH="https://graph.microsoft.com/v1.0",SCOPES="openid profile offline_access User.Read Files.ReadWrite.AppFolder",CLOUD_FILE="business-data.json",LOCAL=CONFIG.storageKey||('tracker:'+INSTALL_ROOT.pathname+':data'),BUILD='5.4.1';
const DEFAULT_PRODUCTS=[{id:'p1',name:'vSeeBox V6 Plus',maker:'vSeeBox',cost:200,typical:265,retail:389},{id:'p2',name:'vSeeBox V6 Replacement Remote',maker:'vSeeBox',cost:10,typical:15,retail:19.99},{id:'p3',name:'We2uSat K3+',maker:'We2uSat',cost:148,typical:225,retail:329},{id:'p4',name:'We2uSat P6 Mini',maker:'We2uSat',cost:160,typical:245,retail:335}],PAYS=['Cash','Venmo','PayPal','Zelle','Credit Card','Check','Bank Transfer','Other'],NAV=['Dashboard','Products','Purchase Orders','Receivables','Sales & Payments','Customers','Expenses','Warranty','Reports','Needs Review','Data Health','History','Settings'];
const EMPTY={schemaVersion:4,orders:[],sales:[],payments:[],expenses:[],claims:[],adjustments:[],history:[],updatedAt:null,settings:{lowStock:{}}};let db=load(),page='Dashboard',syncTimer,syncState='Saved locally',globalQuery='',deferredInstall=null;
const $=s=>document.querySelector(s),money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(Number(n||0)),today=()=>{const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')},uid=p=>p+'-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),pname=id=>products().find(p=>p.id===id)?.name||'Unknown';
function load(){try{let x={...EMPTY,...JSON.parse(localStorage.getItem(LOCAL)||'{}')};x.settings=x.settings||{lowStock:{}};x.settings.lowStock=x.settings.lowStock||{};return x}catch{return structuredClone(EMPTY)}}  
function inventory(){return products().map(p=>{let rec=db.orders.filter(o=>!o.cancelled).flatMap(o=>o.lines||[]).filter(l=>l.productId===p.id).reduce((n,l)=>n+Number(l.received||0),0),sold=db.sales.filter(s=>!s.voided&&s.productId===p.id).reduce((n,s)=>n+Number(s.qty),0),war=db.claims.filter(c=>!c.voided&&c.productId===p.id&&c.replacementSent).reduce((n,c)=>n+Number(c.qty),0),adj=db.adjustments.filter(a=>!a.voided&&a.productId===p.id).reduce((n,a)=>n+Number(a.qty),0);return {...p,onHand:rec-sold-war+adj,received:rec,sold,war}})}

function token(){try{let t=JSON.parse(localStorage.getItem(TOKEN_KEY)||'null');return t&&(t.access_token||t.refresh_token)?t:null}catch{return null}} function setToken(t){localStorage.setItem(TOKEN_KEY,JSON.stringify({...t,expires_at:Date.now()+(+t.expires_in||3600)*1000}))} function b64(a){return btoa(String.fromCharCode(...a)).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')} async function signIn(){if(!CLIENT_ID)return alert('Configure your Microsoft application in app-config.js first.');localStorage.setItem(LOCAL+'-mode','cloud');let v=b64(crypto.getRandomValues(new Uint8Array(64))),c=b64(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(v)))),s=b64(crypto.getRandomValues(new Uint8Array(32)));sessionStorage.pkce=v;sessionStorage.state=s;location.href=AUTH+'/authorize?'+new URLSearchParams({client_id:CLIENT_ID,response_type:'code',redirect_uri:REDIRECT_URI,response_mode:'query',scope:SCOPES,state:s,code_challenge:c,code_challenge_method:'S256'})} async function callback(){let q=new URLSearchParams(location.search),code=q.get('code');if(!code)return;if(q.get('state')!==sessionStorage.state)throw Error('State validation failed');let r=await fetch(AUTH+'/token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({client_id:CLIENT_ID,grant_type:'authorization_code',code,redirect_uri:REDIRECT_URI,code_verifier:sessionStorage.pkce})}),x=await r.json();if(!r.ok)throw Error(x.error_description);setToken(x);history.replaceState({},'',REDIRECT_URI);await firstSync()}
async function access(){let t=token();if(!t)throw Error('Sign in first');if(Date.now()<t.expires_at-60000)return t.access_token;let r=await fetch(AUTH+'/token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({client_id:CLIENT_ID,grant_type:'refresh_token',refresh_token:t.refresh_token,redirect_uri:REDIRECT_URI,scope:SCOPES})}),x=await r.json();if(!r.ok){localStorage.removeItem(TOKEN_KEY);render();throw Error('Microsoft session expired. Select Reconnect Microsoft Account.')}setToken({...t,...x});return x.access_token} async function graph(path,opt={}){let r=await fetch(GRAPH+path,{...opt,headers:{Authorization:'Bearer '+await access(),...(opt.headers||{})}});if(!r.ok)throw Object.assign(Error(await r.text()),{status:r.status});return r}


function customerNames(){return [...new Set([...db.sales.map(s=>s.customer),...db.claims.map(c=>c.customer)].filter(Boolean))].sort((a,b)=>a.localeCompare(b))}
function customerField(value=''){return `<label class="field"><span>Customer${help('Customer')}</span><input name="customer" list="customer-list" autocomplete="off" value="${html(value)}" placeholder="Start typing a customer name"><datalist id="customer-list">${customerNames().map(n=>`<option value="${html(n)}"></option>`).join('')}</datalist></label>`}

function metric(l,v){return `<div class="card metric"><small>${l}</small><strong>${v}</strong></div>`} function field(l,n,t='text',v=''){let step=t==='number'?' step="0.01" inputmode="decimal"':'';return `<label class="field"><span>${l}${help(l)}</span><input name="${n}" type="${t}"${step} value="${v}"></label>`} function select(l,n,opts){return `<label class="field"><span>${l}${help(l)}</span><select name="${n}">${opts.map(x=>`<option value="${x[0]}">${x[1]}</option>`).join('')}</select></label>`} function empty(a){return a.length?'':'<p class="muted">No records yet.</p>'}

let arFilter='Priority',selectedCustomer=null;

function arPriority(x){return x.status==='Credit'?0:x.status==='Due'?1:2}
function receivablesView(){let rows=invoiceRows().filter(x=>arFilter==='Priority'||arFilter==='All'||x.status===arFilter||x.bucket===arFilter);rows.sort((a,b)=>arPriority(a)-arPriority(b)||(a.status==='Credit'?a.balance-b.balance:b.balance-a.balance)||((a.age||-1)<(b.age||-1)?1:-1));let opts=['Priority','All','Due','Credit','Paid','0-30 Days','31-60 Days','61-90 Days','90+ Days','Unknown Date'];return `<div class="card hero"><h1>Receivables Workspace</h1><p class="muted">Credits and balances requiring attention appear first.</p><div class="actions">${opts.map(x=>`<button class="${arFilter===x?'active':''}" onclick="setARFilter('${x}')">${x}</button>`).join('')}</div></div><div class="card">${empty(rows)}${rows.map(x=>`<div class="row"><div><b>${html(x.customer)} · ${html(x.id)}</b><p>${html(pname(x.productId))} · ${html(x.date||'Unknown date')} · ${html(x.bucket)}</p></div><div class="actions"><span class="tag">${x.status==='Credit'?money(Math.abs(x.balance))+' credit':x.status==='Due'?money(x.balance)+' due':'Paid'}</span><button onclick="openCustomer('${escAttr(x.customer)}')">Customer</button><button onclick="voidSale(${actionArg(x.id)})">Return / cancel sale</button>${x.status==='Credit'?`<button class="primary" onclick="manageCredit('${escAttr(x.customer)}')">Manage Credit</button>`:''}${x.balance>0?`<button onclick="createInvoice('${escAttr(x.id)}')">Create Invoice / PDF</button><button class="primary" onclick="pay('${escAttr(x.id)}',${x.balance})">Payment</button>`:''}</div></div>`).join('')}</div>`}
function setARFilter(x){arFilter=x;render()} function escAttr(x){return html(String(x).replace(/\\/g,'\\\\').replace(/'/g,"\\'").replace(/\n/g,'\\n').replace(/\r/g,'\\r'))}
function openCustomer(name){selectedCustomer=name;page='Customers';render()}



function customerDetail(name){let ss=invoiceRows().filter(x=>x.customer===name),ids=ss.map(x=>x.id),pp=db.payments.filter(p=>!p.voided&&ids.includes(p.saleId)),cc=db.claims.filter(c=>!c.voided&&c.customer===name),inv=ss.reduce((n,x)=>n+x.total,0),paid=pp.reduce((n,x)=>n+Number(x.amount||0),0);return `<div class="card hero"><div class="row"><div><h2>${html(name)}</h2><p>${ss.length} invoices · ${unitCount(ss)} units purchased · ${pp.length} payments · ${cc.length} warranty claims</p></div>${customerCredit(name)>0?`<button class="primary" onclick="manageCredit('${escAttr(name)}')">Manage Credit</button>`:''}<button onclick="closeCustomer()">Back to Customers</button></div><div class="grid g3">${metric('Invoiced',money(inv))}${metric('Paid',money(paid))}${metric('Balance Due',money(sumMoney(ss,x=>Math.max(0,x.balance))))}${metric('Customer Credit',money(customerCredit(name)))}</div></div>${creditLedger(name)}<div class="grid g2"><div class="card"><h3>Invoices</h3><button onclick="createStatement(${actionArg(name)})">Customer statement / PDF</button>${empty(ss)}${ss.map(x=>`<div class="row"><div><b>${html(x.id)}</b><p>${html(x.date||'Unknown date')} · ${html(x.bucket)}</p></div><span class="tag">${x.status==='Credit'?money(Math.abs(x.balance))+' credit':money(x.balance)+' due'}</span><button onclick="voidSale(${actionArg(x.id)})">Return / cancel sale</button></div>`).join('')}</div><div class="card"><h3>Payments</h3>${empty(pp)}${pp.map(x=>`<div class="row"><div><b>${html(x.method||'Unknown')}</b><p>${html(x.date||'Unknown date')} · ${html(x.saleId)}</p></div><strong>${money(x.amount)}</strong></div>`).join('')}</div></div><div class="card"><h3>Customer Notes & Collections</h3><p>${html(customerMeta(name).notes||'No customer notes.')}</p><div class="actions">${(customerMeta(name).tags||[]).map(x=>`<span class="tag">${html(x)}</span>`).join('')}<button onclick="editCustomerNotes('${escAttr(name)}')">Edit Notes / Tags</button><button onclick="addCollectionNote('${escAttr(name)}')">Add Collection Note</button></div>${(customerMeta(name).collections||[]).map(x=>`<div class="row"><div><b>${html(x.method)}</b><p>${html(x.date)} · ${html(x.note)}</p></div></div>`).join('')}${attachmentsView('customer',name)}</div><div class="card"><h3>Warranty</h3>${empty(cc)}${cc.map(x=>`<div class="row"><div><b>${html(pname(x.productId))}</b><p>${html(x.status)} · ${html(x.date||'Unknown date')}</p></div><span>${money(x.approvedCredit||0)} approved</span></div>`).join('')}</div>`}
function closeCustomer(){selectedCustomer=null;render()}
function reviewRows(){return (db.reviewQueue||[]).filter(x=>!x.resolved&&!x.ignored)}

function approveUnknown(i){let x=db.reviewQueue[i];x.resolved=true;x.resolution='Approved with unknown historical value';x.resolvedAt=new Date().toISOString();saveLocal('Review item approved',(x.type||'record')+' row '+(x.row||'n/a'))}


function reviewRecord(x){if(x.type==='sale')return db.sales.find(s=>s.sourceRow===x.row);if(x.type==='warranty')return db.claims.find(c=>c.imported&&!c.voided);if(x.type==='inventory')return db.orders.find(o=>o.sourceRow===x.row);return null}
function reviewTitle(x){if(x.type==='sale'&&/missing sale date/i.test(x.issue||''))return 'Sale Date Missing';if(x.type==='sale'&&/zero or negative units/i.test(x.issue||''))return 'Sale Quantity Needs Review';if(x.type==='warranty')return 'Warranty Date Needs Confirmation';if(x.type==='inventory')return 'Purchase Date Missing';return 'Record Needs Review'}
function reviewDetails(x){let r=reviewRecord(x);if(x.type==='sale')return [{label:'Customer',value:r?.customer||x.customer||'Unknown'},{label:'Invoice',value:r?.id||'Imported sale'},{label:'Product',value:r?pname(r.productId):'Unknown'},{label:'Quantity',value:r?.qty??'Unknown'},{label:'Unit Price',value:r?money(r.unitPrice):'Unknown'},{label:'Current Date',value:r?.date||'Not recorded'},{label:'Why this appears',value:x.issue||'Imported data needs confirmation'}];if(x.type==='warranty')return [{label:'Customer',value:r?.customer||x.customer||'Unknown'},{label:'Warranty Claim',value:r?.id||'Imported warranty claim'},{label:'Product',value:r?pname(r.productId):'Unknown'},{label:'Current Date',value:r?.date||'Not recorded'},{label:'Issue',value:r?.issue||x.issue||'Needs confirmation'}];if(x.type==='inventory')return [{label:'Purchase Order',value:r?.id||'Imported purchase order'},{label:'Manufacturer',value:r?.maker||'Unknown'},{label:'Current Date',value:r?.eta||'Not recorded'},{label:'Why this appears',value:x.issue||'Imported data needs confirmation'}];return [{label:'Details',value:x.issue||'Review required'}]}
function toggleReview(i){let el=document.querySelector('#review-details-'+i),btn=document.querySelector('#review-toggle-'+i);if(!el)return;let open=el.hidden;el.hidden=!open;if(btn){btn.textContent=open?'▾':'▸';btn.setAttribute('aria-expanded',String(open))}}
function reviewStatusFilter(mode){db.settings=db.settings||{};db.settings.reviewDisplay=mode;render()}

function needsReviewView(){let all=db.reviewQueue||[],mode=db.settings?.reviewDisplay||'Active',rows=mode==='Active'?all.filter(x=>!x.resolved&&!x.ignored):mode==='Resolved'?all.filter(x=>x.resolved||x.ignored):all;return `<div class="card hero"><h1>Needs Review</h1><p class="muted">${reviewRows().length} active · ${all.length-reviewRows().length} resolved or ignored</p><div class="actions"><button class="${mode==='Active'?'active':''}" onclick="reviewStatusFilter('Active')">Active</button><button class="${mode==='Resolved'?'active':''}" onclick="reviewStatusFilter('Resolved')">Resolved / Ignored</button><button class="${mode==='All'?'active':''}" onclick="reviewStatusFilter('All')">All</button></div></div><div class="card">${empty(rows)}${rows.map(x=>{let i=all.indexOf(x),details=reviewDetails(x),closed=x.resolved||x.ignored;return `<div class="review-item"><div class="review-summary"><button id="review-toggle-${i}" class="disclosure" aria-expanded="false" onclick="toggleReview(${i})">▸</button><button class="review-heading" onclick="toggleReview(${i})"><b>${reviewTitle(x)}</b><span>${html(x.customer||details.find(d=>d.label==='Manufacturer')?.value||'Imported business record')}</span></button><div class="actions">${closed?`<span class="tag">${x.ignored?'Ignored':'Resolved'}</span>`:`<button class="primary" onclick="editReview(${i})">Edit & Resolve</button><button onclick="approveUnknown(${i})">Keep Unknown</button><button class="danger" onclick="ignoreReview(${i})">Ignore</button>`}</div></div><div id="review-details-${i}" class="review-details" hidden>${details.map(d=>`<div><small>${d.label}</small><strong>${html(d.value)}</strong></div>`).join('')}${x.resolution?`<div class="review-resolution"><small>Resolution</small><strong>${html(x.resolution)}</strong></div>`:''}</div></div>`}).join('')}</div>`}

let reportPeriod='All Time';




const WARRANTY_STATUSES=['Reported','Replacement Sent','Submitted to Manufacturer','Approved','Credit Pending','Credit Applied','Denied','Closed'];
const PAYMENT_METHODS=['Cash','Venmo','PayPal','Zelle','Credit Card','Check','Bank Transfer','Customer Credit','Customer Refund','Other'];
function normName(x){return String(x||'').toLowerCase().replace(/[^a-z0-9]/g,'')}
function manufacturers(){return [...new Set([...products().map(p=>p.maker),...db.orders.map(o=>o.maker)].filter(Boolean))].sort()}
function manufacturerField(value='vSeeBox'){return `<label class="field"><span>Manufacturer${help('Manufacturer')}</span><input name="maker" list="manufacturer-list" required value="${html(value)}"><datalist id="manufacturer-list">${manufacturers().map(x=>`<option value="${html(x)}"></option>`).join('')}</datalist></label>`}
function relatedSales(customer){return db.sales.filter(s=>!s.voided&&(!customer||normName(s.customer)===normName(customer)))}



function addAttachment(recordType,recordId,e){let file=e.target.files?.[0];if(!file)return;if(file.size>1500000)return alert('Attachment must be smaller than 1.5 MB.');let reader=new FileReader();reader.onload=()=>{db.attachments=db.attachments||[];db.attachments.push({id:uid('ATT'),recordType,recordId,name:file.name,type:file.type,size:file.size,data:reader.result,date:new Date().toISOString()});saveLocal('Attachment added',recordType+' '+recordId+' · '+file.name)};reader.readAsDataURL(file);e.target.value=''}
function attachmentsView(type,id){let rows=(db.attachments||[]).filter(x=>x.recordType===type&&x.recordId===id);return `<div class="attachments">${rows.map(x=>`<a class="tag" href="${html(/^data:[^,]*;base64,[a-z0-9+/=\s]+$/i.test(x.data||'')?x.data:'#')}" download="${html(x.name)}">${html(x.name)}</a>`).join('')}<label class="btn">Attach File<input hidden type="file" onchange="addAttachment('${escAttr(type)}','${escAttr(id)}',event)"></label></div>`}


function creditInvoices(customer){return invoiceRows().filter(x=>x.customer===customer&&x.balance<-.009)}
function dueInvoices(customer){return invoiceRows().filter(x=>x.customer===customer&&x.balance>.009).sort((a,b)=>b.age-a.age)}


function adjustmentReasonOptions(){return ['Lost','Stolen','Warranty Replacement','Damaged','Demo','Found / Returned','Physical Count Correction','Other']}

function adjustmentLedger(){let rows=db.adjustments.filter(x=>!x.voided);return `<div class="card"><h3>Inventory Adjustment Ledger</h3><p class="muted">All manual additions and deductions require a reason and justification.</p><div class="actions"><button class="primary" onclick="recordInventoryAdjustment()">Record Inventory Adjustment</button></div>${empty(rows)}${rows.map(x=>`<div class="row"><div><b>${html(pname(x.productId))} · ${x.qty>0?'+':''}${html(x.qty)}</b><p>${html(x.type||x.reason||'Adjustment')} · ${html(x.date||'Unknown date')} · ${html(x.notes||'')}</p></div><span class="tag">${x.qty>0?'Added':'Deducted'}</span></div>`).join('')}</div>`}

const HELP={Customer:'Start typing to reuse an existing customer name. A new name creates a new customer automatically.',Product:'Choose the exact product sold so inventory and profit reports remain accurate.',Quantity:'Number of units in this transaction.',Date:'Transaction date used for aging and monthly reporting.','Unit Price':'Sale price per unit before payment activity.','Payment Received':'Money already collected for this sale. This may be zero or partial.','Payment Method':'How the payment was received.','Warranty Credit Applied':'Manufacturer credit used to reduce this purchase order.','Bank/Customs Fees':'Wire fees, customs, duties, or other costs required to receive inventory.',Shipping:'Freight or delivery cost associated with the transaction.','Approved Credit':'Amount the manufacturer approved for a future-order credit.','Replacement Cost':'Your product cost for the replacement unit.'};
function help(label){let x=HELP[label];return x?` <span class="help" tabindex="0" data-tip="${x.replace(/"/g,'&quot;')}">?</span>`:''}

function uploadBranding(e){let file=e.target.files?.[0];if(!file)return;if(!/^image\/(png|jpeg|webp|svg\+xml)$/.test(file.type))return alert('Use PNG, JPG, WEBP, or SVG.');if(file.size>2*1024*1024)return alert('Logo must be smaller than 2 MB.');let reader=new FileReader();reader.onload=()=>{db.settings=db.settings||{};db.settings.brandLogo=reader.result;db.settings.brandFileName=file.name;saveLocal('Branding logo updated',file.name)};reader.readAsDataURL(file)}
function resetBranding(){if(!confirm('Restore the default logo placeholder?'))return;db.settings=db.settings||{};delete db.settings.brandLogo;delete db.settings.brandFileName;saveLocal('Branding logo reset','Default placeholder')}
function downloadPartnerTemplate(){let a=document.createElement('a');a.href='partner-sales-template.csv';a.download='partner-sales-template.csv';a.click()}
function parseCSV(text){let rows=[],row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i],n=text[i+1];if(c==='"'&&quoted&&n==='"'){cell+='"';i++}else if(c==='"')quoted=!quoted;else if(c===','&&!quoted){row.push(cell.trim());cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&n==='\n')i++;row.push(cell.trim());if(row.some(Boolean))rows.push(row);row=[];cell=''}else cell+=c}row.push(cell.trim());if(row.some(Boolean))rows.push(row);return rows}
function normalizeProduct(name){const q=String(name||'').trim().toLowerCase();return products().find(x=>x.name.toLowerCase()===q);}



function partnerSalesCard(){return `<div class="card"><h3>Sales Partner Import ${help('Payment Received')}</h3><p class="muted">Download the template, have the sales partner fill only the essential sale and payment fields, then upload the completed CSV. Imports append sales and never replace existing data. Partner Reference prevents duplicate imports.</p><div class="actions"><button onclick="downloadPartnerTemplate()">Download Sales Template</button><label class="btn primary">Upload Partner Sales CSV<input hidden type="file" accept=".csv,text/csv" onchange="importPartnerSales(event)"></label></div></div>`}

function lowThreshold(id){return Number(db.settings?.lowStock?.[id]??5)}
function lowStockRows(){return inventory().filter(x=>x.onHand<=lowThreshold(x.id))}

function integrityChecks(){let issues=[];for(let x of invoiceRows()){if(x.balance<-.009)issues.push({area:'Receivables',text:x.customer+' has '+money(Math.abs(x.balance))+' credit'});if(!x.date)issues.push({area:'Sales',text:x.id+' is missing a date'})}for(let p of inventory())if(p.onHand<0)issues.push({area:'Inventory',text:p.name+' has negative inventory: '+p.onHand});for(let o of db.orders)if((o.lines||[]).some(l=>Number(l.received||0)>Number(l.qty||0)))issues.push({area:'Purchase Orders',text:o.id+' has received quantity above ordered quantity'});for(let p of db.payments)if(!db.sales.some(s=>s.id===p.saleId))issues.push({area:'Payments',text:p.id+' is not linked to an invoice'});return issues}


function reviewLowStock(id){page='Products';render();setTimeout(()=>setLowStock(id),0)}

function integrityView(){let issues=integrityChecks(),low=lowStockRows();return `<div class="card hero"><h1>Data Health</h1><p class="muted">Automated checks do not modify records.</p></div><div class="grid g3">${metric('Integrity Flags',issues.length)}${metric('Low-Stock Products',low.length)}${metric('Active Review Items',reviewRows().length)}</div><div class="card"><h3>Integrity Flags</h3>${empty(issues)}${issues.map(x=>`<div class="row"><div><b>${x.area}</b><p>${html(x.text)}</p></div><button class="primary" onclick="reviewHealth('${escAttr(x.area)}','${escAttr(x.text)}')">Review</button></div>`).join('')}</div><div class="card"><h3>Low Stock</h3>${empty(low)}${low.map(x=>`<div class="row"><div><b>${html(x.name)}</b><p>Threshold ${lowThreshold(x.id)} · ${x.onHand} on hand</p></div><button onclick="reviewLowStock('${escAttr(x.id)}')">Review Threshold</button></div>`).join('')}</div>`}
function universalSearch(){let q=globalQuery.trim().toLowerCase();if(!q)return'';let rows=[];for(let s of db.sales)if([s.id,s.customer,pname(s.productId),s.date].join(' ').toLowerCase().includes(q))rows.push({type:'Invoice',title:s.id+' · '+s.customer,detail:pname(s.productId)+' · '+(s.date||'Unknown date'),go:`openCustomer('${escAttr(s.customer)}')`});for(let o of db.orders)if([o.id,o.maker,o.status].join(' ').toLowerCase().includes(q))rows.push({type:'PO',title:o.id+' · '+o.maker,detail:o.status,go:"go('Purchase Orders')"});for(let e of db.expenses)if([e.vendor,e.category,e.date,e.notes].join(' ').toLowerCase().includes(q))rows.push({type:'Expense',title:e.vendor,detail:e.category+' · '+(e.date||'Unknown date'),go:"go('Expenses')"});for(let c of db.claims)if([c.customer,pname(c.productId),c.status].join(' ').toLowerCase().includes(q))rows.push({type:'Warranty',title:c.customer+' · '+pname(c.productId),detail:c.status,go:"go('Warranty')"});return `<div class="search-results card"><div class="row"><b>Search Results</b><button onclick="clearSearch()">Close</button></div>${empty(rows)}${rows.slice(0,30).map(x=>`<button class="search-hit" onclick="${x.go}"><span class="tag">${html(x.type)}</span><b>${html(x.title)}</b><small>${html(x.detail)}</small></button>`).join('')}</div>`}
function setGlobalSearch(v){globalQuery=v;let host=document.querySelector('#search-host');if(host)host.innerHTML=universalSearch()} function clearSearch(){globalQuery='';let input=document.querySelector('.global-search');if(input){input.value='';input.focus()}let host=document.querySelector('#search-host');if(host)host.innerHTML=''}
async function cloudBackup(){try{if(!token())return alert('Connect OneDrive first.');await verifyCloudAccount();let name='manual-backup-'+new Date().toISOString().replace(/[:.]/g,'-')+'.json';await graph('/me/drive/special/approot:/'+name+':/content',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(db,null,2)});alert('Created OneDrive backup: '+name)}catch(e){alert('Backup failed: '+e.message)}}
function downloadJSON(){let blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='sickle-scythe-full-backup-'+today()+'.json';a.click();URL.revokeObjectURL(url)}
function printReport(){window.print()}
function installApp(){if(deferredInstall){deferredInstall.prompt();deferredInstall.userChoice.finally(()=>deferredInstall=null)}else alert('Use your browser menu and choose Install app or Add to Home Screen.')}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e})


function poSubtotal(o){return (o.lines||[]).reduce((n,l)=>n+Number(l.qty||0)*Number(l.unitCost||0),0)}
function poTotal(o){return poSubtotal(o)+Number(o.shipping||0)+Number(o.fees||0)-Number(o.credit||0)}
function weightedCosts(){let out={};for(let p of products()){let units=0,cost=0;for(let o of db.orders.filter(o=>!o.cancelled)){let subtotal=poSubtotal(o);for(let l of (o.lines||[]).filter(l=>l.productId===p.id)){let received=Number(l.received||0),base=received*Number(l.unitCost||0),share=subtotal>0?(Number(l.qty||0)*Number(l.unitCost||0))/subtotal:0,landed=base+(Number(o.shipping||0)+Number(o.fees||0)-Number(o.credit||0))*share*(Number(l.qty||0)?received/Number(l.qty):0);units+=received;cost+=landed}}out[p.id]=units>0?cost/units:p.cost}return out}
function csvCell(v){let x=v==null?'':String(v);if(typeof v==='string'&&/^[=+@\-\t\r]/.test(x))x="'"+x;return '"'+x.replace(/"/g,'""')+'"'}
function downloadCSV(name,headers,rows){let csv=[headers.map(csvCell).join(','),...rows.map(r=>r.map(csvCell).join(','))].join('\r\n'),blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name+'-'+today()+'.csv';a.click();URL.revokeObjectURL(url)}
function exportSales(){let wc=weightedCosts();downloadCSV('sales',['Invoice','Date','Customer','Product','Quantity','Unit Price','Revenue','Weighted Unit Cost','COGS','Gross Profit','Balance'],invoiceRows().map(x=>[x.id,x.date,x.customer,pname(x.productId),x.qty,x.unitPrice,x.total,wc[x.productId],x.qty*wc[x.productId],x.total-x.qty*wc[x.productId],x.balance]))}
function exportPayments(){downloadCSV('payments',['Payment ID','Invoice','Date','Method','Amount','Voided'],db.payments.map(x=>[x.id,x.saleId,x.date,x.method,x.amount,!!x.voided]))}
function exportExpenses(){downloadCSV('expenses',['Expense ID','Date','Vendor','Category','Tax Category','Amount','Method','Receipt Status','Notes','Voided'],db.expenses.map(x=>[x.id,x.date,x.vendor,x.category,x.taxCategory||'',x.amount,x.method||'',x.receiptStatus||'',x.notes||'',!!x.voided]))}
function exportInventory(){let wc=weightedCosts();downloadCSV('inventory',['Product','Manufacturer','On Hand','Weighted Landed Unit Cost','Inventory Value','Default Retail'],inventory().map(x=>[x.name,x.maker,x.onHand,wc[x.id],Math.max(0,x.onHand)*wc[x.id],x.retail]))}
function exportReceivables(){downloadCSV('receivables',['Invoice','Customer','Date','Age Bucket','Invoice Total','Paid','Balance','Status'],invoiceRows().filter(x=>Math.abs(x.balance)>.009).map(x=>[x.id,x.customer,x.date,x.bucket,x.total,x.paid,x.balance,x.status]))}
function exportWarranty(){downloadCSV('warranty',['Claim ID','Date','Customer','Product','Status','Replacement Cost','Shipping','Approved Credit','Applied Credit','Remaining Credit'],db.claims.map(x=>[x.id,x.date,x.customer,pname(x.productId),x.status,x.replacementCost,x.shipping,x.approvedCredit,x.appliedCredit,Number(x.approvedCredit||0)-Number(x.appliedCredit||0)]))}
function accountantExports(){return `<div class="card"><h3>Accountant Exports</h3><p class="muted">CSV files open in Excel and use the current OneDrive production database.</p><div class="actions"><button onclick="exportSales()">Sales & Profit</button><button onclick="exportPayments()">Payments</button><button onclick="exportExpenses()">Expenses</button><button onclick="exportInventory()">Inventory Valuation</button><button onclick="exportReceivables()">Receivables</button><button onclick="exportWarranty()">Warranty Credits</button></div></div>`}

function validDate(v){let d=v?new Date(v+'T00:00:00'):null;return d&&!isNaN(d)?d:null}
function periodMatch(date,period=reportPeriod){if(period==='All Time')return true;let d=validDate(date);if(!d)return false;let now=new Date();return period==='This Month'?d.getFullYear()===now.getFullYear()&&d.getMonth()===now.getMonth():period==='This Year'?d.getFullYear()===now.getFullYear():true}
function unitCount(sales){return sales.reduce((n,s)=>n+Number(s.qty||0),0)}
function transactionCount(sales){return sales.length}

function monthKey(date){let d=validDate(date);return d?d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0'):'Unknown'}
function monthlyTrend(){let map=Object.create(null);for(let s of db.sales.filter(s=>!s.voided)){let k=monthKey(s.date);if(k==='Unknown')continue;(map[k]??={revenue:0,collected:0}).revenue+=Number(s.qty||0)*Number(s.unitPrice||0)}for(let p of cashPayments()){let k=monthKey(p.date);if(k==='Unknown')continue;(map[k]??={revenue:0,collected:0}).collected+=Number(p.amount||0)}return Object.entries(map).sort((a,b)=>a[0].localeCompare(b[0])).slice(-12).map(([month,x])=>({month,...x}))}
function arAging(){let out={'0-30 Days':0,'31-60 Days':0,'61-90 Days':0,'90+ Days':0,'Unknown Date':0,'Customer Credits':0};for(let x of invoiceRows()){if(x.balance<-.009)out['Customer Credits']+=Math.abs(x.balance);else if(x.balance>.009)out[x.bucket]+=x.balance}return out}
function topCustomers(){let map=Object.create(null);for(let s of db.sales.filter(s=>!s.voided)){let x=map[s.customer]??={customer:s.customer,revenue:0,units:0};x.revenue+=Number(s.qty||0)*Number(s.unitPrice||0);x.units+=Number(s.qty||0)}return Object.values(map).sort((a,b)=>b.revenue-a.revenue).slice(0,8)}
function productPerformance(){let wc=weightedCosts();return products().map(p=>{let ss=db.sales.filter(s=>!s.voided&&s.productId===p.id),units=ss.reduce((n,s)=>n+Number(s.qty||0),0),revenue=ss.reduce((n,s)=>n+Number(s.qty||0)*Number(s.unitPrice||0),0);return{...p,weightedCost:wc[p.id],units,revenue,gross:revenue-units*wc[p.id],onHand:inventory().find(x=>x.id===p.id)?.onHand||0}}).sort((a,b)=>b.revenue-a.revenue)}
function forecastRows(){let cutoff=new Date();cutoff.setDate(cutoff.getDate()-90);return inventory().map(p=>{let sold90=db.sales.filter(s=>!s.voided&&s.productId===p.id&&validDate(s.date)&&validDate(s.date)>=cutoff).reduce((n,s)=>n+Number(s.qty||0),0),monthly=sold90/3,months=monthly>0?p.onHand/monthly:null;return{...p,sold90,monthly,months}})}
function barRows(rows,label,value,format=money){let max=Math.max(1,...rows.map(value));return rows.map(x=>`<div class="chart-row"><div class="chart-label">${html(label(x))}</div><div class="chart-track"><div class="chart-fill" style="width:${Math.max(2,value(x)/max*100)}%"></div></div><strong>${format(value(x))}</strong></div>`).join('')}

function setReportPeriod(x){reportPeriod=x;render()}
function reportsView(){let f=financials(),aging=arAging(),products=productPerformance(),trend=monthlyTrend(),periods=['All Time','This Year','This Month'];return `<div class="card hero"><h1>Operational Reports</h1><div class="actions"><button onclick="printReport()">Print / Save PDF</button>${periods.map(x=>`<button class="${reportPeriod===x?'active':''}" onclick="setReportPeriod('${x}')">${x}</button>`).join('')}</div></div><div class="grid g4">${metric('Revenue',money(f.revenue))}${metric('Collected',money(f.collected))}${metric('COGS Estimate',money(f.cogs))}${metric('Gross Profit',money(f.gross))}${metric('Expenses',money(f.expenseTotal))}${metric('Estimated Net Profit',money(f.net))}${metric('Units Sold',f.unitsSold)}${metric('Sales Transactions',f.salesTransactions)}${metric('Payments Count',f.payments.length)}</div><div class="grid g2"><div class="card"><h3>Product Performance</h3>${products.map(x=>`<div class="row"><div><b>${html(x.name)}</b><p>${x.units} sold · ${x.onHand} on hand · ${money(x.weightedCost)} landed/unit</p></div><div><strong>${money(x.revenue)}</strong><p>${money(x.gross)} gross estimate</p></div></div>`).join('')}</div><div class="card"><h3>A/R Aging</h3>${Object.entries(aging).map(([k,v])=>`<div class="row"><span>${k}</span><strong>${money(v)}</strong></div>`).join('')}</div></div><div class="card"><h3>12-Month Revenue Trend</h3>${trend.length?barRows(trend,x=>x.month,x=>x.revenue):'<p class="muted">No dated sales available.</p>'}</div>${accountantExports()}`}

function renderBase(){let t=totals(),body='';if(page==='Dashboard')body=dashboardView();
else if(page==='Products')body=productsView();
else if(page==='Purchase Orders')body=ordersView();else if(page==='Receivables')body=receivablesView();else if(page==='Sales & Payments')body=salesView();else if(page==='Customers')body=customersView();else if(page==='Expenses')body=expensesView();else if(page==='Warranty')body=warrantyView();else if(page==='Reports')body=reportsView();else if(page==='Needs Review')body=needsReviewView();else if(page==='Data Health')body=integrityView();else if(page==='History')body=`<div class="card">${empty(db.history)}${db.history.map(h=>`<div class="row"><div><b>${html(h.action)}</b><p>${new Date(h.date).toLocaleString()}</p></div><span>${html(h.detail)}${h.changes?`<details><summary>Before / After</summary><pre>${html(JSON.stringify(h.changes,null,2))}</pre></details>`:''}</span></div>`).join('')}</div>`;else body=settingsView();$('#app').innerHTML=shell(body);updateTopButton()}
function ordersView(){return `<div class="card"><h3>Create Multi-line Purchase Order</h3><form id="po"><div class="fields">${manufacturerField()}${field('ETA','eta','date',today())}${field('Shipping','shipping','number',0)}${field('Bank/Customs Fees','fees','number',0)}${field('Warranty Credit Applied','credit','number',0)}</div><div id="polines"></div><div class="actions"><button type="button" onclick="addPOLine()">Add Product Line</button><button class="primary">Save Purchase Order</button></div></form></div><div class="card"><h3>Purchase Orders</h3>${empty(db.orders)}${db.orders.map(o=>`<div class="row"><div><b>${html(o.id)} · ${html(o.maker)}</b><p>${html(o.lines.map(l=>l.qty+' × '+pname(l.productId)).join(', '))} · ${html(o.status)}</p>${attachmentsView('purchase-order',o.id)}<p> · Subtotal ${money(poSubtotal(o))} · Freight/Fees ${money(Number(o.shipping||0)+Number(o.fees||0))} · Credit ${money(o.credit||0)} · Paid ${money(poTotal(o))}</p></div><div class="actions"><span class="tag">${html(o.cancelled?'Cancelled':o.status)}</span><button onclick="editPO('${escAttr(o.id)}')">Edit</button>${!o.cancelled&&o.status!=='Received'?`<button onclick="receivePO('${escAttr(o.id)}')">Receive</button>`:''}${!o.cancelled?`<details><summary>More actions</summary><button class="danger" onclick="cancelPO('${escAttr(o.id)}')">Cancel</button></details>`:''}</div></div>`).join('')}</div>`}
