function salesView(){return `<nav class="actions sales-shortcuts" aria-label="Sales shortcuts"><button onclick="jumpSales('record-sale')">Record Sale</button><button onclick="jumpSales('invoice-list')">Invoices</button><button class="primary" onclick="showPayments()">Payments &amp; Receipts</button></nav><details class="card"><summary>Import partner sales</summary>${partnerSalesCard()}</details><div class="card" id="record-sale"><h3>Record Sale</h3><form id="sale" oninput="updateSalePreview()"><div class="fields">${customerField()}${select('Product','productId',activeProducts().map(p=>[p.id,p.name])).replace('<select ', '<select onchange="saleProductChanged(this)" ')}${field('Quantity','qty','number',1)}${field('Unit Price','unitPrice','number',activeProducts()[0]?.typical||0)}${field('Date','date','date',today())}${field('Payment received (optional)','received','number',0)}${select('Payment method','method',PAYS.map(x=>[x,x]))}${field('Reference','reference')}</div><p id="sale-preview" role="status"></p><div class="actions"><button class="primary">Save Sale</button><button type="button" onclick="resetDraft('sale');updateSalePreview()">Clear draft</button></div></form></div><div class="card" id="invoice-list"><h3>Invoices</h3>${empty(db.sales)}${db.sales.map(s=>{let paid=db.payments.filter(p=>!p.voided&&p.saleId===s.id).reduce((n,p)=>n+Number(p.amount||0),0),bal=s.qty*s.unitPrice-paid;return `<div class="row"><div><b>${html(s.id)} · ${html(s.customer)}</b><p>${html(pname(s.productId))} · ${money(paid)} paid</p></div><div><span class="tag">${s.voided?'Voided':bal<0?money(-bal)+' credit':money(bal)+' due'}</span> <button onclick="showPayments(${actionArg(s.id)})">View Payments</button><button onclick="editSale('${escAttr(s.id)}')">Edit</button>${!s.voided?`<button onclick="voidSale(${actionArg(s.id)})">Return / cancel sale</button>`:''} ${!s.voided&&bal>0?`<button onclick="createInvoice('${escAttr(s.id)}')">Invoice / PDF</button><button onclick="pay('${escAttr(s.id)}',${bal})">Payment</button>`:''}</div></div>`}).join('')}</div>${paymentHistory()}`}
function customersView(){if(selectedCustomer)return customerDetail(selectedCustomer);let names=[...new Set(db.sales.filter(s=>!s.voided).map(s=>s.customer))],rows=names.map(n=>{let ss=invoiceRows().filter(x=>x.customer===n),balance=ss.reduce((a,x)=>a+x.balance,0),paid=ss.reduce((a,x)=>a+x.paid,0);return{name:n,count:ss.length,units:unitCount(ss),balance,paid}}).sort((a,b)=>(a.balance<0?0:a.balance>0?1:2)-(b.balance<0?0:b.balance>0?1:2)||Math.abs(b.balance)-Math.abs(a.balance));return `<div class="card">${empty(rows)}${rows.map(x=>`<div class="row"><div><b>${html(x.name)}</b><p>${x.count} invoices · ${x.units} units · ${money(x.paid)} paid</p></div><div class="actions"><span class="tag">${money(sumMoney(invoiceRows().filter(i=>i.customer===x.name),i=>Math.max(0,i.balance)))} due · ${money(customerCredit(x.name))} credit</span><button onclick="openCustomer('${escAttr(x.name)}')">Open Profile</button></div></div>`).join('')}</div>`}
function expensesView(){return `<div class="card"><h3>Add Expense</h3><form id="expense"><div class="fields">${field('Vendor','vendor')}${field('Category','category','text','Shipping')}${field('Amount','amount','number',0)}${field('Date','date','date',today())}</div><button class="primary">Save Expense</button></form></div><div class="card">${empty(db.expenses)}${db.expenses.map(e=>`<div class="row"><div><b>${html(e.vendor)}</b><p>${html(e.category)} · ${html(e.date)}</p>${attachmentsView('expense',e.id)}</div><div class="actions"><strong>${money(e.amount)}</strong><button onclick="editExpense('${escAttr(e.id)}')">Edit</button>${!e.voided?`<details><summary>More actions</summary><button class="danger" onclick="voidExpense('${escAttr(e.id)}')">Void</button></details>`:''}</div></div>`).join('')}</div>`}
function warrantyView(){return `<div class="card"><h3>Warranty Claim</h3><form id="claim"><div class="fields">${customerField()}${select('Product','productId',products().map(p=>[p.id,p.name]))}${field('Quantity','qty','number',1)}${field('Replacement Cost','replacementCost','number',200)}${field('Shipping','shipping','number',0)}${field('Approved Credit','approvedCredit','number',0)}${field('Date','date','date',today())}${select('Status','status',WARRANTY_STATUSES.map(x=>[x,x]))}${select('Related Sale','relatedSaleId',[['','None'],...db.sales.filter(s=>!s.voided).map(s=>[s.id,s.customer+' · '+s.id+' · '+pname(s.productId)])])}</div><button class="primary">Save Claim</button></form></div><div class="card">${empty(db.claims)}${db.claims.map(c=>`<div class="row"><div><b>${html(c.customer)} · ${html(pname(c.productId))}</b><p>${html(c.status)} · Cost ${money(c.replacementCost+c.shipping)}${html(c.relatedSaleId?' · Sale '+c.relatedSaleId:'')}</p>${attachmentsView('warranty',c.id)}</div><div class="actions"><strong>${money(c.approvedCredit-c.appliedCredit)} credit</strong><button onclick="editClaim('${escAttr(c.id)}')">Edit</button>${!c.voided?`<details><summary>More actions</summary><button class="danger" onclick="voidClaim('${escAttr(c.id)}')">Void</button></details>`:''}</div></div>`).join('')}</div>`}

