function shell(body){const primary=['Dashboard','Sales & Payments','Customers'];return `<div class="shell ${menuOpen?'menu-open':''}"><aside class="side" aria-label="All sections"><div class="brand"><img src="${html(brandingLogo())}" alt=""><div><b>${html(businessName())}</b><div class="muted">Business Tracker v${BUILD}</div></div></div><nav class="nav">${NAV.filter(n=>!primary.includes(n)).map(n=>`<button class="${page===n?'active':''}" onclick="go('${n}')">${n}</button>`).join('')}</nav></aside><main class="main"><header class="top"><div><small class="mobile-brand">${html(businessName())} · v${BUILD}</small><h2>${html(page)}</h2></div><div class="top-tools"><input aria-label="Search records" class="global-search" value="${html(globalQuery)}" oninput="setGlobalSearch(this.value)" placeholder="Search records…"></div></header><div class="content">${syncBanner()}<div id="search-host">${universalSearch()}</div>${body}</div></main><nav class="primary-nav" aria-label="Main navigation">${primary.map(n=>`<button class="${page===n?'active':''}" onclick="go('${n}')">${n}</button>`).join('')}<button aria-expanded="${menuOpen}" onclick="toggleMenu()">More</button></nav><button id="back-to-top" class="back-to-top" onclick="backToTop()" hidden aria-label="Back to top">↑ Top</button></div>`;}
