function captureDrafts(){if(!renderedPage)return;for(const form of document.querySelectorAll('#app form')){const fields=[...form.querySelectorAll('input,select,textarea')].filter(e=>e.type!=='file').map(e=>({name:e.name,value:e.value,checked:e.checked}));drafts.set(renderedPage+':'+form.id,{fields,poLines:form.id==='po'?form.querySelector('#polines')?.innerHTML:null});}}
