function dashboardView(){const f=financials('All Time'),t=totals(),due=invoiceRows().filter(x=>x.balance>0),pending=db.orders.filter(x=>!x.cancelled&&x.status!=='Received').length;return `<div class="grid g4 dashboard-totals">${metric('Outstanding balances',money(t.ar))}${metric('Customer credits',money(t.customerCredits))}${metric('Inventory on hand',t.onHand+' units')}${metric('Cash collected · all time',money(f.collected))}</div><div class="card"><h3>Needs your attention</h3><div class="attention-grid"><button onclick="go('Receivables')">${due.length} invoices with a balance<small>${due.filter(x=>x.age!==null&&x.age>30).length} older than 30 days</small></button><button onclick="go('Purchase Orders')">${pending} purchase orders to receive</button><button onclick="go('Products')">${lowStockRows().filter(x=>!x.archived).length} products at low stock</button><button onclick="go('Warranty')">${money(t.credit)} manufacturer credit</button><button onclick="go('Needs Review')">${reviewRows().length} records to review</button></div></div><div class="actions quick-actions"><button class="primary" onclick="go('Sales & Payments');jumpSales('record-sale')">New sale</button><button onclick="go('Sales & Payments');showPayments()">Find payment / receipt</button><button onclick="go('Expenses')">Record expense</button></div><details class="card"><summary>More business totals & trends</summary><div class="grid g3">${metric('Revenue · all time',money(f.revenue))}${metric('Units Sold',f.unitsSold)}${metric('Sales Transactions',f.salesTransactions)}${metric('Estimated Net Profit',money(f.net))}${metric('Inventory value',money(t.invValue))}</div><h3>Monthly revenue</h3>${barRows(monthlyTrend(),x=>x.month,x=>x.revenue)}<p class="muted">Undated records count in all-time totals. Profit uses weighted landed-cost estimates.</p><button onclick="go('Reports')">Open reports</button></details>`;}
