function editPO(id){const o=db.orders.find(x=>x.id===id);if(!o||o.cancelled)return;openEditor('Edit purchase order',field('ETA (blank if unknown)','eta','date')+field('Shipping','shipping','number')+field('Bank/customs fees','fees','number')+o.lines.map((l,i)=>field(pname(l.productId)+' quantity','qty'+i,'number',l.qty)+field('Unit cost','cost'+i,'number',l.unitCost)).join('')+'<p class="muted">Manufacturer and allocated warranty credit remain linked to this order.</p>',f=>{const changes={eta:optionalDate(f.eta),shipping:nonnegative(f.shipping),fees:nonnegative(f.fees)},lines=o.lines.map((l,i)=>({...l,qty:whole(f['qty'+i]),unitCost:nonnegative(f['cost'+i])}));if(lines.some(l=>l.qty<Number(l.received||0)))throw Error('Ordered quantity cannot be lower than quantity received.');return commitFinancial('Purchase order edited',()=>Object.assign(o,changes,{lines}));},o);}
