async function verifyCloudAccount(){const me=await(await graph('/me?$select=id')).json();if(!me.id)throw Error('Cannot verify the Microsoft account.');const bound=localStorage.getItem(LOCAL+'-account');if(bound&&bound!==me.id)throw Error('This device belongs to a different Microsoft account. Sign in to the original account, or back up and clear this device before switching.');return me.id;}
