function signOut(){if(syncBusy)return alert('Wait for sync to finish before signing out.');if(!confirm('Sign out on this device? Your local copy will be retained. Download a backup first if changes are waiting to sync.'))return;clearTimeout(syncTimer);localStorage.removeItem(TOKEN_KEY);localStorage.setItem(LOCAL+'-locked','yes');cloudHealthy=false;render();}
function clearDevice(){if(syncBusy)return alert('Wait for sync to finish before clearing this device.');openEditor('Clear this device',`<p>This removes this installation’s cached records and sign-in. It does not delete OneDrive files. Any unsynced changes will be lost. Keep a downloaded backup first.</p><button type="button" onclick="downloadJSON()">Download Local Backup</button>${field('Type CLEAR after keeping your backup','confirm')}`,f=>{if(f.confirm!=='CLEAR')throw Error('Type CLEAR to confirm.');clearTimeout(syncTimer);for(const key of [LOCAL,TOKEN_KEY,SYNC_KEY,LOCAL+'-account',LOCAL+'-locked',LOCAL+'-mode',LOCAL+'-restore-review'])localStorage.removeItem(key);db=structuredClone(EMPTY);syncMeta={};lastLocalJSON=null;localConflict=false;cloudHealthy=false;syncError='';drafts.clear();renderedPage='';page='Dashboard';render();}, {},'Clear device');}
function checkBackup(data){validateCloudData(data);validateRecordShapes(data);function walk(x){if(!x||typeof x!=='object')return;for(const [key,value] of Object.entries(x)){if(['__proto__','prototype','constructor'].includes(key))throw Error('This backup contains an unsupported property.');if(typeof value==='number'&&!Number.isFinite(value))throw Error('This backup contains an invalid number.');walk(value);}}walk(data);for(const type of ['orders','sales','payments','expenses','claims','adjustments','history']){const ids=new Set();for(const x of data[type]||[]){if(!x||typeof x!=='object'||typeof x.id!=='string'||!x.id||ids.has(x.id))throw Error('Check missing or duplicate IDs in '+type+'.');ids.add(x.id);}}if(data.settings!==undefined&&(!data.settings||typeof data.settings!=='object'||Array.isArray(data.settings)))throw Error('Invalid business settings.');return structuredClone(data);}
function backupComparison(data){return ['orders','sales','payments','expenses','claims','adjustments','history'].map(type=>({type,current:(db[type]||[]).length,backup:(data[type]||[]).length}));}
function restoreBackup(data,expected){if(syncBusy)throw Error('Wait for sync to finish before restoring.');assertLocalCurrent();if(JSON.stringify(db)!==expected)throw Error('Records changed since this comparison. Reopen the backup preview.');const candidate=checkBackup(data),previous=structuredClone(db);clearTimeout(syncTimer);const wasPending=restorePending();localStorage.setItem(LOCAL+'-restore-review','yes');const ok=commitFinancial('Backup restored on device',()=>{const seen=new Set((candidate.history||[]).map(x=>x.id));db={...structuredClone(EMPTY),...candidate};db.history=[...(candidate.history||[]),...previous.history.filter(x=>!seen.has(x.id))];db.settings||={lowStock:{}};});if(!ok&&!wasPending)localStorage.removeItem(LOCAL+'-restore-review');return ok;}
async function previewBackup(e){const file=e.target.files?.[0];e.target.value='';if(!file)return;try{if(file.size>20*1024*1024)throw Error('Choose a JSON backup smaller than 20 MB.');const data=checkBackup(JSON.parse(await file.text())),expected=JSON.stringify(db),rows=backupComparison(data);openEditor('Review backup before restoring',`<p>No records have changed. This replaces records on this device, preserves audit history from both copies, and pauses cloud uploads.</p><table class="comparison"><thead><tr><th>Records</th><th>This device</th><th>Backup</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${html(x.type)}</td><td>${x.current}</td><td>${x.backup}</td></tr>`).join('')}</tbody></table><p>Settings: ${stableJSON(db.settings)===stableJSON(data.settings)?'same':'different'}. Backup saved: ${html(data.updatedAt||'date not recorded')}.</p><button type="button" onclick="downloadJSON()">Download current copy first</button>${field('Type RESTORE after keeping the current backup','confirm')}`,f=>{if(f.confirm!=='RESTORE')throw Error('Type RESTORE to confirm.');return restoreBackup(data,expected);},{},'Restore on this device');}catch(err){alert('Backup could not be opened: '+err.message);}}
async function uploadRestoredData(){if(!restorePending())return;if(!confirm('Upload the restored copy to OneDrive? Review totals and keep both backups first. Saving will stop if OneDrive has changed since this device last synced.'))return;localStorage.removeItem(LOCAL+'-restore-review');const ok=await cloudSave(true);if(!ok)localStorage.setItem(LOCAL+'-restore-review','yes');render();if(ok)alert('Restored copy saved to OneDrive.');}
async function useCloudCopy(){if(!confirm('Replace this device’s records with OneDrive? Keep a local backup first.'))return;downloadJSON();if(await cloudLoad(false,true)){localStorage.removeItem(LOCAL+'-restore-review');render();}}
function settingsView(){return `<div class="grid g2"><div class="card"><h3>Storage & account</h3><p>${localOnly()?'Local-only: records stay in this browser. Download backups regularly.':'OneDrive is your private source of truth. This browser keeps an offline copy.'}</p><div class="actions"><button onclick="downloadJSON()">Download Local Backup</button>${localOnly()?'':token()?'<button onclick="cloudLoad()">Load Cloud</button><button onclick="cloudSave()">Save Cloud</button><button onclick="signOut()">Sign out</button>':'<button onclick="signIn()">Reconnect to OneDrive</button>'}${!hasBusinessRecords()&&!token()?'<button onclick="startLocal()">Start local-only business</button>':''}</div><details><summary>Device & account options</summary><p>Local data is stored unencrypted in this browser. Use a trusted, locked device. Clearing this device does not delete OneDrive files.</p><button onclick="clearDevice()">Back up & clear this device</button></details></div><div class="card"><h3>Backup & recovery</h3><div class="actions"><button onclick="downloadJSON()">Download Full JSON</button>${!localOnly()?'<button onclick="cloudBackup()">Create OneDrive Backup</button>':''}<label class="btn">Review backup to restore<input hidden type="file" accept=".json,application/json" onchange="previewBackup(event)"></label></div>${restorePending()?'<p class="notice">Restoration is local until you deliberately upload it.</p><button onclick="uploadRestoredData()">Upload reviewed restoration</button><button onclick="useCloudCopy()">Discard restoration & load OneDrive</button>':''}</div><div class="card"><h3>Business identity</h3><p>${html(businessName())}</p><div class="brand-preview"><img src="${html(brandingLogo())}" alt="Business logo"><span>${html(db.settings?.brandFileName||'Default logo')}</span></div><div class="actions"><button onclick="editBusinessName()">Edit business name</button><label class="btn">Upload logo<input hidden type="file" accept="image/png,image/jpeg,image/webp,image/svg+xml" onchange="uploadBranding(event)"></label><button onclick="resetBranding()">Default logo</button></div><p class="muted">Identity and logo stay in your private business settings.</p></div><div class="card"><h3>Set up your own copy</h3><p>Use a local server for local-only operation, or configure your own Microsoft application for OneDrive. Never use someone else’s registration for a new business.</p><a class="btn" href="https://github.com/SeanRiggs/sickle-scythe-business-tracker/blob/main/docs/SETUP.md" target="_blank" rel="noopener">Setup guide</a>${CONFIG.allowNewCloudBusiness?'<button onclick="createNewCloudBusiness()">Create a new OneDrive business</button>':''}<button onclick="installApp()">Install app</button></div>${accountantExports()}</div>`;}
function editBusinessName(){openEditor('Business name',field('Business name','businessName','text',businessName()),f=>{const name=requiredText(f.businessName,'Business name');return commitFinancial('Business name updated',()=>db.settings.businessName=name);});}
function statementHTML(name){const invoices=invoiceRows().filter(x=>x.customer===name),ids=new Set(invoices.map(x=>x.id)),payments=db.payments.filter(p=>ids.has(p.saleId)&&!p.voided);return documentHTML('Customer statement',`<h2>${html(name)}</h2><p>As of ${html(new Date().toLocaleDateString())}</p><div class="summary"><b>Balance due ${money(sumMoney(invoices,x=>Math.max(0,x.balance)))}</b><b>Available credit ${money(customerCredit(name))}</b></div><h2>Invoices</h2>${invoices.map(x=>`<section><b>${html(x.id)}</b><p>${html(x.date||'Date not recorded')} · ${html(pname(x.productId))} × ${html(x.qty)}</p><p>Total ${money(x.total)} · ${x.balance<0?'Credit '+money(-x.balance):'Balance '+money(x.balance)}</p></section>`).join('')}<h2>Payments & credit movements</h2>${payments.map(x=>`<section><b>${money(x.amount)} · ${html(x.method||'Method not recorded')}</b><p>${html(x.date||'Date not recorded')} · ${html(x.saleId)}</p></section>`).join('')||'<p>No payments recorded.</p>'}`);}
function documentHTML(title,body){return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${html(title)}</title><style>body{font:16px/1.5 system-ui,sans-serif;margin:auto;padding:20px;max-width:760px;color:#17202a}img{max-width:80px;max-height:70px}h1{font-size:24px}h2{font-size:20px}section{padding:12px 0;border-bottom:1px solid #ddd;break-inside:avoid}.summary{display:flex;flex-wrap:wrap;gap:16px;padding:16px;background:#f4f4f4}button{font:inherit;padding:12px;border:0;border-radius:8px;background:#7f1d1d;color:#fff}@media print{button{display:none}body{padding:0;font-size:11pt}}</style></head><body><button onclick="print()">Print / Save as PDF</button><p><img alt="" src="${html(brandingLogo())}"></p><h1>${html(businessName())}</h1><h2>${html(title)}</h2>${body}</body></html>`;}
function openDocument(content){const url=URL.createObjectURL(new Blob([content],{type:'text/html'})),w=window.open(url,'_blank');if(!w){URL.revokeObjectURL(url);return alert('Allow popups to open this document.');}w.opener=null;setTimeout(()=>URL.revokeObjectURL(url),60000);}
function createStatement(name){openDocument(statementHTML(name));}
function invoiceHTML(id){const x=invoiceRows().find(x=>x.id===id);if(!x)throw Error('Invoice not found.');return documentHTML('Invoice '+x.id,`<h2>${html(x.customer)}</h2>${x.date?`<p>Invoice date: ${html(x.date)}</p>`:''}<section>${html(pname(x.productId))} × ${html(x.qty)}<p>Total ${money(x.total)}</p><p>Payments ${money(x.paid)}</p></section><div class="summary"><b>Balance due ${money(Math.max(0,x.balance))}</b></div><p>Thank you for your business. Please reference ${html(x.id)} with payment.</p>`);}
function createInvoice(id){try{openDocument(invoiceHTML(id))}catch(e){alert(e.message)}}
async function initializeCloudBusiness(name){if(!CONFIG.allowNewCloudBusiness||hasBusinessRecords()||syncMeta.baseHash||localStorage.getItem(LOCAL+'-account')||restorePending())throw Error('New-business setup is only available on a fresh, explicitly configured installation.');if(syncBusy)throw Error('Wait for the current sync to finish.');assertLocalCurrent();syncBusy=true;const before=JSON.stringify(db);try{const accountId=await verifyCloudAccount();let missing=false;try{await graph('/me/drive/special/approot:/'+CLOUD_FILE+'?$select=id');}catch(e){if(e.status===404)missing=true;else throw e;}if(!missing)throw Error('A database already exists. Reconnect and load it instead.');const candidate=structuredClone(EMPTY);candidate.settings={lowStock:{},products:[],businessName:requiredText(name,'Business name')};const folder=await(await graph('/me/drive/special/approot?$select=id')).json();if(!folder.id)throw Error('Could not verify the application folder.');assertLocalCurrent();if(JSON.stringify(db)!==before)throw Error('Local records changed. Setup stopped.');const session=await(await graph('/me/drive/items/'+encodeURIComponent(folder.id)+':/'+CLOUD_FILE+':/createUploadSession',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({item:{'@microsoft.graph.conflictBehavior':'fail',name:CLOUD_FILE}})})).json();const url=new URL(session.uploadUrl);if(url.protocol!=='https:')throw Error('Invalid upload session.');const bytes=new TextEncoder().encode(JSON.stringify(candidate)),response=await fetch(url.href,{method:'PUT',headers:{'Content-Type':'application/octet-stream','Content-Range':`bytes 0-${bytes.length-1}/${bytes.length}`},body:bytes});if(![200,201].includes(response.status))throw Error('New-business creation was not confirmed. Reconnect to check the folder before retrying.');const remote=await cloudSnapshot();if(remote.hash!==await dataHash(candidate))throw Error('The new database could not be verified. Reconnect before continuing.');assertLocalCurrent();if(JSON.stringify(db)!==before)throw Error('Local records changed. The cloud copy was created, but this device was not replaced.');db=candidate;lastLocalJSON=JSON.stringify(db);localStorage.setItem(LOCAL,lastLocalJSON);localStorage.setItem(LOCAL+'-account',accountId);localStorage.setItem(LOCAL+'-mode','cloud');storeSync({baseHash:remote.hash,localHash:remote.hash,itemId:remote.id,etag:remote.etag,dirty:false});cloudHealthy=true;syncError='';render();return true;}finally{syncBusy=false;}}
function createNewCloudBusiness(){if(!token())return alert('Connect your own Microsoft account first. Then return to this explicit new-business action.');const d=openEditor('Create a new OneDrive business',`<p>For a fresh installation only. Existing databases are never replaced. Your registration must support App Folder uploads; setup stops if the service refuses access.</p>${field('Business name','businessName')}${field('Type CREATE','confirm')}`,f=>{if(f.confirm!=='CREATE')throw Error('Type CREATE to confirm.');d.querySelector('button.primary').disabled=true;initializeCloudBusiness(f.businessName).then(()=>d.close()).catch(e=>{d.querySelector('.editor-error').textContent=e.message;d.querySelector('button.primary').disabled=false;});return false;},{},'Create empty business');}

function createPO(f,lines){const maker=requiredText(f.maker,'Manufacturer'),shipping=nonnegative(f.shipping),fees=nonnegative(f.fees),credit=nonnegative(f.credit),eta=optionalDate(f.eta);if(!lines.length)throw Error('Add at least one product line.');lines=lines.map(l=>{knownProduct(l.productId);return{productId:l.productId,qty:whole(l.qty),unitCost:nonnegative(l.unitCost),received:0};});const claims=db.claims.filter(c=>!c.voided&&products().find(p=>p.id===c.productId)?.maker===maker);if(cents(credit)>claims.reduce((n,c)=>n+Math.max(0,cents(c.approvedCredit||0)-cents(c.appliedCredit||0)),0))throw Error('The requested manufacturer credit is not available.');let remaining=cents(credit);for(const c of claims){const use=Math.min(remaining,Math.max(0,cents(c.approvedCredit||0)-cents(c.appliedCredit||0)));c.appliedCredit=(cents(c.appliedCredit||0)+use)/100;remaining-=use;}db.orders.unshift({id:uid('PO'),maker,eta,shipping,fees,credit,lines,status:'Ordered'});}
document.addEventListener('submit',e=>{if(!['sale','po','expense','claim'].includes(e.target.id))return;e.preventDefault();e.stopImmediatePropagation();const f=Object.fromEntries(new FormData(e.target)),id=e.target.id;const ok=commitFinancial(id==='sale'?'Sale and payment recorded':id==='po'?'Purchase order created':id==='expense'?'Expense created':'Warranty claim created',()=>{if(id==='sale')createSale(f);if(id==='po')createPO(f,[...e.target.querySelectorAll('.po-line')].map(x=>({productId:x.querySelector('[name=lineProduct]').value,qty:x.querySelector('[name=lineQty]').value,unitCost:x.querySelector('[name=lineCost]').value})));if(id==='expense')db.expenses.unshift({id:uid('EXP'),vendor:requiredText(f.vendor,'Vendor'),category:f.category,amount:nonnegative(f.amount),date:paymentDate(f.date)});if(id==='claim'){knownProduct(f.productId);if(!WARRANTY_STATUSES.includes(f.status))throw Error('Choose a warranty status.');if(f.relatedSaleId&&!db.sales.some(s=>s.id===f.relatedSaleId&&normName(s.customer)===normName(f.customer)))throw Error('Related invoice must belong to this customer.');db.claims.unshift({...f,id:uid('WR'),customer:requiredText(f.customer,'Customer'),date:paymentDate(f.date),qty:whole(f.qty),replacementCost:nonnegative(f.replacementCost),shipping:nonnegative(f.shipping),approvedCredit:nonnegative(f.approvedCredit),appliedCredit:0,replacementSent:f.status==='Replacement Sent'});}});if(ok){resetDraft(id);render();}},true);
function editReview(i){const x=db.reviewQueue?.[i];if(!x)return;const r=reviewRecord(x),dateField=x.type==='inventory'?'eta':'date';openEditor(reviewTitle(x),r?field('Confirmed date (blank keeps unknown)','date','date',r[dateField]||''):field('Resolution note','note'),f=>{const date=optionalDate(f.date);return commitFinancial('Review item resolved',()=>{if(r){r[dateField]=date;x.resolution=date?'Date confirmed':'Date remains unknown';}else x.resolution=requiredText(f.note,'Resolution note');x.resolved=true;x.resolvedAt=new Date().toISOString();});});}
function reasonDialog(title,onSave){openEditor(title,field('Reason','reason'),f=>onSave(requiredText(f.reason,'Reason')),{},title);}
function ignoreReview(i){reasonDialog('Ignore review item',why=>commitFinancial('Review item ignored',()=>Object.assign(db.reviewQueue[i],{ignored:true,resolution:why,resolvedAt:new Date().toISOString()})));}
function voidPayment(id){const p=db.payments.find(x=>x.id===id);if(!p||p.voided)return;reasonDialog(isTransfer(p)?'Reverse Credit Transfer':'Void Payment',why=>commitFinancial('Payment reversed / voided',()=>voidPaymentRecord(id,why)));}
function returnSaleInput(fields){
 const reason=requiredText(fields.reason,'Reason');
 if(!['returned-resellable','never-delivered'].includes(fields.stock))throw Error('Confirm that every unit is back in resellable stock or was never delivered.');
 return {reason,stock:fields.stock};
}
function returnSaleRecord(id,fields){
 const sale=activeSale(id),{reason,stock}=returnSaleInput(fields);
 if(db.payments.some(p=>!p.voided&&p.saleId===id))throw Error('This invoice has payment or credit activity. Review the money received and any refund before cancelling the sale.');
 const qty=whole(sale.qty);knownProduct(sale.productId);
 Object.assign(sale,{voided:true,voidReason:reason,voidedAt:new Date().toISOString(),cancellation:{stock,qty,reason}});
 // Inventory already excludes voided sales. An extra adjustment would double-restock.
}
function voidSale(id){
 const sale=activeSale(id),invoice=invoiceRows().find(x=>x.id===id);
 if(db.payments.some(p=>!p.voided&&p.saleId===id)){
   return openEditor('Review payment before return',`<p>${html(sale.customer)} · ${html(id)}</p><p>This invoice has payments or credit movements. A return must also account for the money received. Nothing has been changed.</p><p>Review the payment history before deciding on a refund or credit. Do not void a real payment just to cancel the sale.</p>`,()=>{showPayments(id);}, {},'View payments');
 }
 return openEditor('Return / cancel sale',`<p><strong>${html(sale.customer)}</strong><br>${html(id)}<br>${html(pname(sale.productId))} × ${html(sale.qty)}</p><p>Balance removed: <strong>${money(invoice.balance)}</strong><br>Inventory restored: <strong>${html(sale.qty)} unit(s)</strong><br>No payment or refund will be recorded. The original sale stays in History and the invoice list as voided.</p>${select('Where are all the units?','stock',[['','Choose before confirming'],['returned-resellable','Returned — all units are resellable'],['never-delivered','Never delivered — all units are still in stock']])}${field('Reason','reason')}<p>For a partial return, damaged item, or missing unit, cancel this form and review the inventory separately.</p>`,f=>{const values=returnSaleInput(f);return commitFinancial('Sale returned / cancelled',()=>returnSaleRecord(id,values));},{},'Confirm return / cancellation');
}
function voidExpense(id){reasonDialog('Void expense',why=>commitFinancial('Expense voided',()=>Object.assign(db.expenses.find(x=>x.id===id),{voided:true,voidReason:why})));}
function voidClaim(id){const c=db.claims.find(x=>x.id===id);if(Number(c?.appliedCredit)>0)return alert('This claim has manufacturer credit applied to a purchase order. Review that allocation before voiding.');reasonDialog('Void warranty claim',why=>commitFinancial('Warranty claim voided',()=>Object.assign(c,{voided:true,voidReason:why})));}
function cancelPO(id){const o=db.orders.find(x=>x.id===id);if(o.lines.some(l=>Number(l.received)>0)||Number(o.credit)>0)return alert('This order has received stock or allocated manufacturer credit. Review those movements before cancelling.');reasonDialog('Cancel purchase order',why=>commitFinancial('Purchase order cancelled',()=>Object.assign(o,{cancelled:true,cancelReason:why,status:'Cancelled'})));}
function reviewHealth(area){go(({Receivables:'Receivables',Sales:'Needs Review',Inventory:'Products','Purchase Orders':'Purchase Orders',Payments:'Sales & Payments'})[area]||'Needs Review');}
function importPartnerSales(e){const file=e.target.files?.[0];e.target.value='';if(!file)return;return file.text().then(text=>{const rows=parseCSV(text),headers=(rows.shift()||[]).map(x=>x.toLowerCase());for(const name of ['Sale Date','Customer','Product','Quantity','Unit Price'])if(!headers.includes(name.toLowerCase()))throw Error('Missing column: '+name);let added=0,skipped=0;const ok=commitFinancial('Partner sales imported',()=>{for(const row of rows){const at=n=>row[headers.indexOf(n.toLowerCase())]||'',product=normalizeProduct(at('Product'));if(!product)throw Error('A product could not be matched. Use its exact catalog name.');const f={date:at('Sale Date'),customer:at('Customer'),productId:product.id,qty:at('Quantity'),unitPrice:at('Unit Price'),received:at('Payment Received')||0,method:at('Payment Method'),notes:at('Notes'),reference:at('Partner Reference')},key=f.reference||[f.date,f.customer,product.id,Number(f.qty),Number(f.unitPrice)].join('|');if(db.sales.some(s=>s.partnerImportKey===key)){skipped++;continue;}const sale=createSale(f);Object.assign(sale,{partnerReference:f.reference,partnerImportKey:key,importedFromPartner:true});added++;}});if(ok)alert(`${added} sales added. ${skipped} duplicates skipped.`);}).catch(e=>alert('Import stopped: '+e.message));}


function validateRecordShapes(data){
 const numeric={sales:['qty','unitPrice'],payments:['amount'],orders:['shipping','fees','credit'],expenses:['amount'],claims:['qty','replacementCost','shipping','approvedCredit','appliedCredit'],adjustments:['qty']};
 for(const [type,fields] of Object.entries(numeric))for(const row of data[type]||[]){
  if(!row||typeof row!=='object'||Array.isArray(row))throw Error('Invalid record in '+type+'.');
  for(const key of fields)if(row[key]!==undefined&&row[key]!==null&&(!['number','string'].includes(typeof row[key])||!Number.isFinite(Number(row[key]))))throw Error('Invalid '+key+' in '+type+'.');
  for(const key of ['customer','productId','maker','vendor','method','saleId','status'])if(row[key]!==undefined&&typeof row[key]!=='string')throw Error('Invalid '+key+' in '+type+'.');
 }
 for(const order of data.orders){if(!Array.isArray(order.lines))throw Error('Purchase order lines are missing.');for(const line of order.lines){if(!line||typeof line.productId!=='string')throw Error('Invalid purchase order product.');for(const key of ['qty','unitCost','received'])if(line[key]!==undefined&&!Number.isFinite(Number(line[key])))throw Error('Invalid purchase order quantity or cost.');}}
 for(const key of ['reviewQueue','attachments'])if(data[key]!==undefined&&!Array.isArray(data[key]))throw Error('Invalid '+key+'.');
 const settings=data.settings||{};
 if(settings.products!==undefined){if(!Array.isArray(settings.products))throw Error('Invalid product catalog.');const ids=new Set();for(const p of settings.products){if(!p||typeof p.id!=='string'||!p.id||ids.has(p.id)||typeof p.name!=='string'||typeof p.maker!=='string')throw Error('Invalid product catalog entry.');ids.add(p.id);for(const key of ['cost','typical','retail'])if(!Number.isFinite(Number(p[key])))throw Error('Invalid product price.');}}
 if(settings.customers!==undefined){if(!settings.customers||typeof settings.customers!=='object'||Array.isArray(settings.customers))throw Error('Invalid customer settings.');for(const m of Object.values(settings.customers)){if(!m||typeof m!=='object'||m.tags!==undefined&&!Array.isArray(m.tags)||m.collections!==undefined&&!Array.isArray(m.collections))throw Error('Invalid customer profile.');}}
}
function poProductChanged(el){const p=products().find(p=>p.id===el.value);if(p)el.closest('.po-line').querySelector('[name=lineCost]').value=p.cost;}

Object.assign(window,{createReceipt,backToTop,useCloudCopy});
render();if(page==='Purchase Orders')addPOLine();
if(new URLSearchParams(location.search).has('code'))callback().catch(syncFailure);else if(token()&&!localOnly())firstSync().catch(syncFailure);
